/* Live Discover UI — mobile-first flow from DISCOVER-HANDOFF.md. */
(()=>{
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['Suit','Shirt','Jacket','Trousers','Dress','Blazer','Vest','Shoes','Belt','Sunglasses','Jewellery'];
const countries={in:'India',us:'United States',gb:'United Kingdom',ae:'UAE'};
let source='',crop={left:0,top:0,width:100,height:100},a={category:'',colour:'',fit:'',pattern:'',details:'',subtype:'',features:''},market='in',budget='',data=null,busy='',error='',uncertainty='',caps=null,abort=null,version=0,save=()=>{},step='crop',selected=null,filter='in',detected=null,detectNote='';
let progress=0,stage='',started=0,ticker,drag=null;
const attrs=()=>[a.colour,a.fit,a.pattern].filter(Boolean).join(' · ')||'Review the details before searching';
const itemName=()=>[a.colour,a.subtype||a.category].filter(Boolean).join(' ')||a.category;
const field=(name,label,value,placeholder='')=>`<label class="field">${label}<input data-discovery-field="${name}" value="${esc(value)}" maxlength="150" placeholder="${esc(placeholder)}"></label>`;
function reset(image){clearInterval(ticker);abort?.abort();version++;source=image;crop={left:0,top:0,width:100,height:100};a={category:'',colour:'',fit:'',pattern:'',details:'',subtype:'',features:''};data=null;busy='';error='';uncertainty='';step='crop';selected=null;filter='in';detected=null;detectNote='';}
function targetChips(){return `<div class="discover-targets" aria-label="Choose a garment">${categories.map(c=>`<button data-discovery="target" data-value="${c}" class="discover-chip ${a.category===c?'active':''}">${c}</button>`).join('')}<button data-discovery="custom-target" class="discover-chip">Other</button></div>`;}
function dock(label,action,disabled=false,secondary=''){return `<div class="discover-dock">${secondary}<button class="discover-primary" data-discovery="${action}" ${disabled?'disabled':''}>${label}</button></div>`;}
function cropScreen(){return `<div id="live-discovery" class="discover-flow"><div class="discover-stepbar"><button data-action="go" data-value="discover">← Back</button><span>Step 1 of 2</span></div><h1>What caught your eye?</h1><p class="discover-sub">One piece at a time. Drag the frame around it.</p><div class="discover-crop"><img src="${esc(source)}" alt="Your screenshot" id="crop-source"><div id="crop-box" style="left:${crop.left}%;top:${crop.top}%;width:${crop.width}%;height:${crop.height}%"><i data-handle="nw"></i><i data-handle="ne"></i><i data-handle="sw"></i><i data-handle="se"></i></div></div><div class="discover-crop-help"><span>Drag corners to adjust</span><button data-discovery="reset-crop">Use full image</button></div>${a.category?`<p class="discover-sub">Searching for: <strong>${esc(a.category)}</strong> <button class="link-btn" data-discovery="custom-target">Change</button></p>`:''}${targetChips()}${detectNote?`<div class="discover-warning">${esc(detectNote)}</div>`:error?`<div class="discover-warning" role="alert">${esc(error)}</div>`:caps&&!caps.vision?'<div class="discover-warning">AI description is unavailable. You can enter the details manually.</div>':''}${dock('Describe this piece with AI →','analyze',!caps?.vision||!a.category)}</div>`;}
function pickScreen(){return `<div id="live-discovery" class="discover-flow"><div class="discover-stepbar"><button data-action="go" data-value="discover">← Back</button><span>Step 1 of 2</span></div><h1>What would you like to find?</h1><p class="discover-sub">We spotted a few things in your photo — pick one to search for.</p><div class="discover-pick-grid">${detected.map((it,i)=>`<button class="discover-pick-item" data-discovery="pick-item" data-index="${i}">${it.thumb?`<img src="${esc(it.thumb)}" alt="${esc(it.label)}">`:''}<strong>${esc(it.label)}</strong></button>`).join('')}</div><button class="link-btn" data-discovery="skip-pick">None of these — crop manually</button></div>`;}
function confirmScreen(){return `<div id="live-discovery" class="discover-flow"><div class="discover-stepbar"><button data-discovery="back-crop">← Back</button><span>Step 2 of 2</span></div><h1>Here's what we found.</h1><p class="discover-sub">Review it, then search for matches.</p><article class="discover-ai-card"><img src="${esc(source)}" alt="Selected crop"><div><span class="discover-ai-badge">Described by AI</span><h2>${esc(itemName())}</h2><p>${esc(attrs())}</p></div></article><details class="discover-edit"><summary>Edit details</summary><div class="discover-fields">${field('subtype','Specific piece',a.subtype,'e.g. button-up shirt')}${field('colour','Colour',a.colour)}${field('fit','Fit / shape',a.fit)}${field('pattern','Pattern',a.pattern)}${field('details','Details that matter',a.details)}${field('features','Defining features',a.features,'e.g. sherpa collar, sleeveless')}</div></details><div class="discover-two"><label class="field">Shopping destination<select data-discovery-field="market">${Object.entries(countries).map(([v,t])=>`<option value="${v}" ${market===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Max budget<input data-discovery-field="budget" type="number" min="1" value="${esc(budget)}" placeholder="Optional"></label></div>${error?`<div class="discover-warning" role="alert">${esc(error)}</div>`:uncertainty?`<div class="discover-warning">${esc(uncertainty)}</div>`:''}<p class="discover-provider-note">Your crop is sent to configured shopping providers. A temporary link expires in five minutes.</p>${dock('Find shopping matches →','search',!caps?.shopping)}</div>`;}
function loading(){const thresholds=[40,60,82,100];return `<div id="live-discovery" class="discover-flow discover-searching" aria-busy="true"><div class="search-thumb"><img src="${esc(source)}" alt="Your selected piece"><span></span></div><h1>${esc(busy||'Working')}</h1><p class="discover-sub">${a.colour||a.subtype?`${esc(itemName())} · ${esc(countries[market])}`:'Hang tight — this only takes a moment.'}</p><div class="discover-progress"><div style="width:${Math.max(8,progress)}%"></div></div><div class="progress-line"><span>${esc(stage||'Candidates')}</span><strong id="search-elapsed">${Math.floor((Date.now()-started)/1000)}s</strong></div><div class="stage-grid">${['Candidates','Stores','Comparing','Best picks'].map((t,i)=>`<div class="${progress>=thresholds[i]?'done':progress>=([10,40,60,82][i])?'active':''}"><i></i>${t}</div>`).join('')}</div>${dock('Cancel','cancel',false)}</div>`;}
function confidence(p){if(!p.priceText)return 'Price unknown';const fit=p.breakdown?.find(x=>x.key==='fit')?.value,colour=p.breakdown?.find(x=>x.key==='colour')?.value;return p.score!==null&&fit>=70&&colour>=70?'Close match':'Similar shape';}
function compactHeader(sub){return `<div class="discover-result-head"><img src="${esc(source)}" alt="Reference"><div><strong>${esc(itemName())}</strong><span>${esc(sub)}</span></div><button data-action="go" data-value="discover/select">Refine</button></div>`;}
function card(p){return `<button class="discover-product" data-discovery="detail" data-id="${p.id}"><div class="product-image">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.title)}" loading="lazy" referrerpolicy="no-referrer">`:''}<span>${esc(confidence(p))}</span></div><strong>${esc(p.title)}</strong><small>${esc(p.merchant)} · ${esc(p.priceText||'at retailer')}</small></button>`;}
function emptyResults(global){return `<div id="live-discovery" class="discover-flow">${compactHeader('India · no close match')}<section class="discover-empty"><h1>Nothing close in India yet.</h1><p>Two global options sit closer to your reference.</p><div class="global-rows">${global.slice(0,2).map(p=>`<button data-discovery="detail" data-id="${p.id}">${p.image?`<img src="${esc(p.image)}" alt="">`:''}<span><strong>${esc(p.title)}</strong><small>${esc(p.priceText||'at retailer')}</small></span><b>Global</b></button>`).join('')}</div><button class="action-row" data-discovery="relax-colour">Drop the colour filter <span>→</span></button><button class="action-row" data-action="go" data-value="discover/select">Try a tighter crop <span>→</span></button><p>Import cost, delivery time and returns are shown by the retailer.</p></section>${dock('Show global options →','show-global',!global.length)}</div>`;}
function detail(p){const facts=[['Colour',a.colour||'Not confirmed'],['Fit',a.fit||'Not confirmed'],['Pattern',a.pattern||'Not confirmed']];return `<div id="live-discovery" class="discover-flow"><div class="discover-stepbar"><button data-discovery="back-results">← Back</button><span>${data.results.indexOf(p)+1} of ${data.results.length}</span></div><div class="detail-image">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.title)}">`:''}<span>${esc(confidence(p))}</span></div><h1 class="detail-title">${esc(p.title)}</h1><p class="discover-sub">${esc(p.merchant)} · ${esc(p.priceText||'at retailer')}</p><div class="fact-grid">${facts.map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><details class="discover-edit"><summary>Why this match</summary><p>${esc(p.reasons?.[0]||'Its visible shape and details are similar to your selected piece.')}</p></details>${dock('Open at retailer →','open-retailer',false,`<button class="discover-save" data-discovery="save" data-id="${p.id}">Save</button>`)}</div>`;}
function results(){if(!data)return cropScreen();if(selected){const p=data.results.find(x=>x.id===selected);if(p)return detail(p);selected=null;}const domestic=data.results.filter(p=>p.market==='in'),global=data.results.filter(p=>p.market==='global');if(data.market==='in'&&!domestic.length)return emptyResults(global);const visible=(filter==='global'?global:domestic.length?domestic:data.results);return `<div id="live-discovery" class="discover-flow">${compactHeader(`${data.results.length} matches · ${countries[data.market]}`)}<div class="result-filters"><button class="${filter==='in'?'active':''}" data-discovery="filter" data-value="in">India ${domestic.length}</button><button class="${filter==='global'?'active':''}" data-discovery="filter" data-value="global">Global ${global.length}</button></div><div class="discover-grid">${visible.map(card).join('')}</div><p class="discover-provider-note">Price, size and delivery are confirmed on the retailer's page.</p></div>`;}
function selection(ref){if(source!==ref.image){reset(ref.image);request('detect');}if(busy)return loading();return step==='confirm'?confirmScreen():step==='pick'?pickScreen():cropScreen();}
function repaint(){const el=document.querySelector('#live-discovery');if(el)el.outerHTML=location.hash.includes('/results')?results():selection({image:source});}
async function cropTo(imgSrc,c){const image=new Image();image.src=imgSrc;await image.decode();const x=image.naturalWidth*c.left/100,y=image.naturalHeight*c.top/100,w=image.naturalWidth*c.width/100,h=image.naturalHeight*c.height/100,scale=Math.min(1,1200/Math.max(w,h)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(w*scale));canvas.height=Math.max(1,Math.round(h*scale));canvas.getContext('2d').drawImage(image,x,y,w,h,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.88);}
async function cropped(){return cropTo(source,crop);}
async function request(action){if(busy)return;const current=++version;abort=new AbortController();busy=action==='detect'?'Finding items in your photo':action==='analyze'?'Describing your piece':'Finding matches';error='';progress=0;stage=busy;started=Date.now();clearInterval(ticker);ticker=setInterval(()=>{const el=document.querySelector('#search-elapsed');if(el)el.textContent=Math.floor((Date.now()-started)/1000)+'s';},1000);repaint();try{const image=action==='detect'?source:await cropped();if(current!==version)return;const response=await fetch('/api/discover/'+action,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/x-ndjson'},body:JSON.stringify(action==='detect'?{image}:action==='analyze'?{image,category:a.category}:{image,attributes:a,market,budget}),signal:abort.signal});let result;if(!response.ok){const failure=await response.json();throw Error(failure.error||'Search could not complete.');}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {done,value}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split('\n');buffer=lines.pop();for(const line of lines){if(!line.trim())continue;const event=JSON.parse(line);if(event.type==='progress'){progress=Math.max(progress,event.percent);stage=event.label;repaint();}if(event.type==='error')throw Error(event.error);if(event.type==='result')result=event.data;}if(done)break;}if(!result)throw Error('Connection interrupted. Please retry.');if(current!==version)return;if(action==='detect'){const items=Array.isArray(result.items)?result.items:[];const withThumbs=[];for(const it of items){try{withThumbs.push({...it,thumb:await cropTo(source,it.crop)});}catch{}}detected=withThumbs;if(detected.length>1)step='pick';else if(detected.length===1){crop=detected[0].crop;a.category=detected[0].label;step='crop';}else{detectNote="Couldn't automatically spot items in this photo — choose what you're looking for below.";step='crop';}}else if(action==='analyze'){a=Object.fromEntries(['category','colour','fit','pattern','details','subtype','features'].map(k=>[k,result[k]||'']));uncertainty=result.uncertainty;step='confirm';}else{data=result;filter=data.results.some(p=>p.market==='in')?'in':'global';location.hash='discover/results';}}catch(e){if(current===version&&e.name!=='AbortError')error=e instanceof TypeError?'Could not reach the server. Check your connection and try again.':e.message;}finally{if(current===version){clearInterval(ticker);busy='';repaint();}}}
function updateCrop(e){if(!drag)return;const dx=(e.clientX-drag.x)/drag.rect.width*100,dy=(e.clientY-drag.y)/drag.rect.height*100,c={...drag.crop};if(drag.handle.includes('w')){c.left=Math.max(0,Math.min(c.left+dx,c.left+c.width-15));c.width=drag.crop.width-(c.left-drag.crop.left);}if(drag.handle.includes('e'))c.width=Math.max(15,Math.min(100-c.left,drag.crop.width+dx));if(drag.handle.includes('n')){c.top=Math.max(0,Math.min(c.top+dy,c.top+c.height-15));c.height=drag.crop.height-(c.top-drag.crop.top);}if(drag.handle.includes('s'))c.height=Math.max(15,Math.min(100-c.top,drag.crop.height+dy));crop=c;const box=document.querySelector('#crop-box');if(box)Object.assign(box.style,{left:c.left+'%',top:c.top+'%',width:c.width+'%',height:c.height+'%'});}
document.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-handle]');if(h){e.preventDefault();drag={handle:h.dataset.handle,x:e.clientX,y:e.clientY,crop:{...crop},rect:h.closest('.discover-crop').getBoundingClientRect()};h.setPointerCapture?.(e.pointerId);}});document.addEventListener('pointermove',updateCrop);document.addEventListener('pointerup',()=>{drag=null;});
document.addEventListener('input',e=>{const t=e.target;if(!t.dataset.discoveryField)return;const k=t.dataset.discoveryField;if(k==='market')market=t.value;else if(k==='budget')budget=t.value;else a[k]=t.value;data=null;});
document.addEventListener('click',e=>{const b=e.target.closest('[data-discovery]');if(!b||b.disabled)return;const x=b.dataset.discovery;if(x==='analyze'||x==='search')request(x);if(x==='target'){a.category=b.dataset.value;repaint();}if(x==='custom-target'){const v=prompt('What piece are you looking for?',a.category);if(v){a.category=v.slice(0,120);repaint();}}if(x==='reset-crop'){crop={left:0,top:0,width:100,height:100};repaint();}if(x==='back-crop'){step='crop';repaint();}if(x==='cancel'){clearInterval(ticker);version++;abort?.abort();busy='';repaint();}if(x==='pick-item'){const it=detected[Number(b.dataset.index)];if(it){crop=it.crop;a.category=it.label;step='crop';}repaint();}if(x==='skip-pick'){crop={left:0,top:0,width:100,height:100};detectNote='';step='crop';repaint();}if(x==='filter'){filter=b.dataset.value;repaint();}if(x==='detail'){selected=b.dataset.id;repaint();}if(x==='back-results'){selected=null;repaint();}if(x==='show-global'){filter='global';repaint();}if(x==='relax-colour'){a.colour='';location.hash='discover/select';step='confirm';repaint();}if(x==='save'){const p=data?.results.find(p=>p.id===b.dataset.id);if(p)save({...p,category:a.category});}if(x==='open-retailer'){const p=data?.results.find(p=>p.id===selected);if(p)window.open(p.url,'_blank','noopener,noreferrer');}});
window.addEventListener('hashchange',()=>{if(!location.hash.includes('discover')){clearInterval(ticker);version++;abort?.abort();busy='';}});
window.Discovery={selection,results,onSave:fn=>save=fn};
fetch('/api/discover/status').then(r=>r.json()).then(v=>{caps=v;repaint();}).catch(()=>{caps={};error='Cannot reach the discovery server.';repaint();});
})();
